#!/usr/bin/env python3
import csv, gzip, io, json, sys, os
from collections import defaultdict
from datetime import datetime, timedelta, timezone, date
from fractions import Fraction
from zoneinfo import ZoneInfo

UTC = timezone.utc
EPOCH = datetime(1970, 1, 1, tzinfo=UTC)


def read_text(path):
    with open(path, 'rb') as f:
        data = f.read()
    if data[:2] == b'\x1f\x8b':
        data = gzip.decompress(data)
    return data.decode('utf-8-sig')


def lines_of(path):
    return [l for l in read_text(path).splitlines() if l.strip()]


def to_ts(dt):
    return int((dt - EPOCH).total_seconds())


def local_to_ts(zone, naive, fold=0):
    return to_ts(naive.replace(tzinfo=zone, fold=fold))


def std_offset(zone):
    offs = [datetime(2026, m, 1, tzinfo=zone).utcoffset() for m in (1, 7)]
    return min(offs)


def parse_abbr(path, zone):
    out = []
    header = None
    for line in lines_of(path):
        row = next(csv.reader([line]))
        row = [c.strip() for c in row]
        if 'Badge' in row and 'Punch' in row:
            header = row
            continue
        if header is None:
            continue
        r = dict(zip(header, row))
        m, d, y = map(int, r['Date'].split('/'))
        t = r['Time'].strip().upper()
        ampm = None
        if t.endswith('AM') or t.endswith('PM'):
            ampm = t[-2:]
            t = t[:-2].strip()
        hh, mm, ss = map(int, t.split(':'))
        if ampm:
            hh %= 12
            if ampm == 'PM':
                hh += 12
        naive = datetime(y, m, d, hh, mm, ss)
        fold = 0 if r['Zone'].strip().upper().endswith('DT') else 1
        out.append((r['Record'], r['Badge'], r['Punch'].upper(), local_to_ts(zone, naive, fold)))
    return out


