    out = []
    schema = 1
    for line in lines_of(path):
        o = json.loads(line)
        if 'schema' in o and 'id' not in o and 'punch_id' not in o:
            schema = o['schema']
            continue
        if o.get('heartbeat'):
            continue
        if schema == 2:
            if 'punch_id' not in o:
                continue
            ts = int(o['epoch_ms']) // 1000
            out.append((str(o['punch_id']), o['employee'], o['direction'].upper(), ts))
        else:
            if 'id' not in o:
                continue
            if 'ts_ms' in o:
                ts = int(o['ts_ms']) // 1000
            else:
                ts = int(o['ts'])
            out.append((str(o['id']), o['emp'], o['dir'].upper(), ts))
    return out


def parse_offset(path):
    out = []
    text = lines_of(path)
    rows = csv.reader(text, delimiter=';', quotechar='"')
    header = None
    for row in rows:
        if header is None or 'punch_id' in row:
            header = row
            continue
        r = dict(zip(header, row))
        dt = datetime.fromisoformat(r['timestamp'])
        d = 'IN' if r['event'].strip() == 'clock_in' else 'OUT'
        out.append((r['punch_id'], r['employee'], d, to_ts(dt)))
    return out


def parse_legacy(path, zone):
    out = []
    off = std_offset(zone)
    for line in lines_of(path):
        t = line[0]
        if t == 'H':
            s = line[13:18].strip()
            if s and s[0] in '+-':
                sec = (int(s[1:3]) * 60 + int(s[3:5])) * 60
                off = timedelta(seconds=-sec if s[0] == '-' else sec)
            else:
                off = std_offset(zone)
        elif t == 'D':
            pid = line[1:9]
            badge = 'E' + line[9:15].strip()
            d = 'IN' if line[15] == 'I' else 'OUT'
            dt = datetime.strptime(line[16:30], '%Y%m%d%H%M%S')
            out.append((pid, badge, d, to_ts(dt.replace(tzinfo=UTC) - off)))
    return out


def parse_de(path, zone):
