    header = None
    for line in lines_of(path):
        row = [c.strip() for c in line.split('\t')]
        if 'Ausweis' in row:
            header = row
            continue
        if header is None:
            continue
        r = dict(zip(header, row))
        dd, mo, yy = map(int, r['Datum'].split('.'))
        hh, mm = map(int, r['Uhrzeit'].split(':')[:2])
        fold = 0 if r['Zeitzone'].upper() == 'MESZ' else 1
        d = 'IN' if r['Buchung'].upper() == 'K' else 'OUT'
        out.append((r['Nr'], r['Ausweis'], d, local_to_ts(zone, datetime(yy, mo, dd, hh, mm), fold)))
    return out


