        o = json.loads(line)
        p = o.get('punch')
        if not p:
            continue
        naive = datetime.strptime(p['at'], '%Y-%m-%d %H:%M:%S')
        out.append((str(p['id']).strip(), p['badge'], p['type'].upper(), local_to_ts(zone, naive, 0)))
    return out


