    pend = date.fromisoformat(period['end'])
    cutoff = to_ts(datetime.fromisoformat(period['corrections_cutoff'].replace('Z', '+00:00')))

    def rows(name):
        with open(os.path.join(indir, name), newline='', encoding='utf-8-sig') as f:
            return [{k.strip(): (v or '').strip() for k, v in r.items()} for r in csv.DictReader(f)]

    sites = {r['site']: (ZoneInfo(r['timezone']), r['format']) for r in rows('sites.csv')}
    emps = rows('employees.csv')
    emp_home = {r['employee_id']: ZoneInfo(sites[r['home_site']][0].key) for r in emps}
    rates = defaultdict(list)
    from decimal import Decimal
    for r in rows('rates.csv'):
        rates[r['employee_id']].append((date.fromisoformat(r['effective_from']), Fraction(Decimal(r['hourly_rate']))))
    for v in rates.values():
        v.sort()

    punches = {}   # (site, id) -> [emp, dir, ts]
    ever = set()
    for site, (zone, fmt) in sites.items():
        d = os.path.join(indir, 'exports', site)
