            elif fmt == 'epoch-jsonl': recs = parse_epoch(path)
            elif fmt == 'offset-csv': recs = parse_offset(path)
            elif fmt == 'legacy-fixed': recs = parse_legacy(path, zone)
            elif fmt == 'de-tsv': recs = parse_de(path, zone)
            elif fmt == 'local-csv': recs = parse_local_csv(path, zone)
            elif fmt == 'local-jsonl': recs = parse_local_jsonl(path, zone)
            else: raise SystemExit('unknown format ' + fmt)
            for pid, emp, dr, ts in recs:
                k = (site, pid)
                ever.add(k)
                if k not in punches:
                    punches[k] = [emp, dr, ts]

