                r = {k.strip(): (v or '').strip() for k, v in r.items() if k}
                if not r.get('correction_id'):
                    continue
                r['_t'] = to_ts(datetime.fromisoformat(r['issued_at'].replace('Z', '+00:00')))
                corr.append(r)
    corr.sort(key=lambda r: (r['_t'], r['correction_id']))
    applied = 0
    voided = set()
    for r in corr:
        if r['_t'] > cutoff:
            continue
        k = (r['site'], r['punch_id'])
        a = r['action']
        if a == 'void':
            if k in punches:
                del punches[k]; voided.add(k); applied += 1
        elif a == 'set':
            if k in punches:
                punches[k][2] = to_ts(datetime.fromisoformat(r['time'].replace('Z', '+00:00')))
                applied += 1
        elif a == 'add':
            if k not in ever:
                ever.add(k)
                punches[k] = [r['employee'], r['type'].upper(),
                              to_ts(datetime.fromisoformat(r['time'].replace('Z', '+00:00')))]
                applied += 1

