           for e in emps}
    exc = dict(open_shifts=0, orphan_outs=0, duplicates_dropped=0, corrections_applied=applied)

    for emp, lst in by_emp.items():
        lst.sort()
        kept = []
        last = None
        for ts, _, site, pid, dr in lst:
            rts = round_ts(ts, sites[site][0])
            if last is not None and last[4] == dr and ts - last[0] <= 300:
                if inp(workday(rts, emp)):
                    exc['duplicates_dropped'] += 1
                continue
            last = (ts, _, site, pid, dr)
            kept.append((rts, dr, site))
        shifts = []
        pend_in = None

        def open_(p):
            if inp(workday(p[0], emp)):
                exc['open_shifts'] += 1
        for rts, dr, site in kept:
            if dr == 'IN':
                if pend_in:
                    open_(pend_in)
                pend_in = (rts, site)
            else:
                if pend_in and rts - pend_in[0] <= 16 * 3600:
                    shifts.append((pend_in[0], rts, pend_in[1]))
                else:
                    if pend_in:
                        open_(pend_in)
                    if inp(workday(rts, emp)):
                        exc['orphan_outs'] += 1
                pend_in = None
        if pend_in:
            open_(pend_in)

        sh = []
        for i, o, site in shifts:
            wd = workday(i, emp)
            if not inp(wd):
                continue
            worked = max(0, (o - i) // 60)
            paid = worked - 30 if worked > 360 else worked
            zone = sites[site][0]
            night = 0
            ld = datetime.fromtimestamp(i, UTC).astimezone(zone).date() - timedelta(days=1)
            while True:
                ws = local_to_ts(zone, datetime(ld.year, ld.month, ld.day, 22))
                nd = ld + timedelta(days=1)
                we = local_to_ts(zone, datetime(nd.year, nd.month, nd.day, 6))
                if ws >= o:
                    break
                night += max(0, min(o, we) - max(i, ws))
                ld = nd
            night = min(night // 60, paid)
            sh.append((i, wd, paid, night))
        sh.sort()
        daily = defaultdict(int)
        weekly = defaultdict(int)
        rl = rates[emp]
        r = res[emp]
        for i, wd, paid, night in sh:
            dot = max(0, daily[wd] + paid - 480) - max(0, daily[wd] - 480)
            daily[wd] += paid
            wk = wd - timedelta(days=wd.weekday())
            nondaily = paid - dot
            wot = max(0, weekly[wk] + nondaily - 2400) - max(0, weekly[wk] - 2400)
            weekly[wk] += nondaily
            ot = dot + wot
            reg = paid - ot
            rate = Fraction(0)
            for ef, hr in rl:
                if ef <= wd:
                    rate = hr
            if not rate and rl and rl[0][0] > wd:
                rate = rl[0][1]
            r['shifts'] += 1
            r['paid_minutes'] += paid
            r['overtime_minutes'] += ot
            r['night_minutes'] += night
            r['pay'] += rate * (reg + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * night / 60

    def money(fr):
        cents = (fr * 100 + Fraction(1, 2)).__floor__()
        return '%d.%02d' % divmod(cents, 100)

    out_emps = {}
    tot = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0)
    totc = 0
    for e, r in res.items():
        g = money(r['pay'])
        out_emps[e] = {k: r[k] for k in tot}
        out_emps[e]['gross'] = g
        for k in tot:
            tot[k] += r[k]
        totc += int(g.replace('.', ''))
    tot['gross'] = '%d.%02d' % divmod(totc, 100)
    with open(outfile, 'w') as f:
        json.dump({'period': {'start': period['start'], 'end': period['end']},
                   'employees': out_emps, 'exceptions': exc, 'totals': tot}, f, indent=1)


main()
